<?php
/**
 * Stateless HMAC-based CSRF tokens.
 * Token format: timestamp.random.hmac
 * Verified against the application key. Valid for 2 hours.
 */
declare(strict_types=1);

/**
 * Resolve the HMAC signing key for CSRF tokens.
 *
 * Prefers APP_KEY from api/.env. If that's unset (e.g. a fresh deploy where
 * the operator hasn't filled in .env yet), fall back to a persistent,
 * auto-generated key stored at api/storage/.app_key — the same zero-config
 * spirit as the SQLite auto-migrate in db.php. Without this, a single unset
 * variable returns an empty key, /csrf answers 503 csrf_not_configured, and
 * every CSRF-gated form (application, newsletter, contact) fails at once.
 * Setting APP_KEY in .env always takes precedence over the generated key.
 */
function mam_app_key(): string {
    static $key = null;
    if ($key !== null) return $key;

    $env = trim((string)mam_env('APP_KEY', ''));
    if (strlen($env) >= 32) return $key = $env;

    $file = MAM_STORAGE . '/.app_key';
    if (is_readable($file)) {
        $stored = trim((string)@file_get_contents($file));
        if (strlen($stored) >= 32) return $key = $stored;
    }

    // First boot without a configured key: generate one and persist it so it
    // stays stable across requests (tokens minted now must verify later).
    if (!is_dir(MAM_STORAGE)) @mkdir(MAM_STORAGE, 0750, true);
    $generated = bin2hex(random_bytes(32));
    if (@file_put_contents($file, $generated, LOCK_EX) !== false) {
        @chmod($file, 0600);
        if (function_exists('mam_log')) {
            mam_log('warn', 'app_key_autogenerated', [
                'hint' => 'APP_KEY is empty in api/.env — generated a persistent fallback at storage/.app_key so forms work. Set a real APP_KEY (32+ chars) in .env for full control.',
            ]);
        }
        return $key = $generated;
    }

    /* ⚠️ THE WRITE FAILED, AND THIS IS THE WORST STATE THE APP CAN BE IN.
       Returning the generated key anyway gives every PHP process a DIFFERENT
       signing key, so nothing signed in one request verifies in the next:

         · every CSRF token is rejected — the whole site's forms stop
           submitting, with `csrf_invalid` and no other symptom;
         · every attendance QR, faculty invite link, application draft key and
           unsubscribe link becomes unverifiable.

       MEASURED with the persist blocked: three consecutive processes minted
       three unrelated keys. It is silent, it is total, and it looks like a
       front-end bug — which is why it is logged at ERROR with the real
       consequence, and why `mam_app_key_persisted()` exists for the health
       route and the console to report rather than guess.

       ⚠️ There is deliberately NO fallback to a world-writable directory.
       This key signs attendance and invitation tokens; on the shared hosting
       this academy runs on, a key in a shared /tmp is a worse failure than a
       broken form. An unwritable storage directory is an operator fix
       (`chmod`/`chown` on api/storage, or set APP_KEY in api/.env), and
       inventing somewhere else to put a secret is not this function's call. */
    $GLOBALS['__mam_app_key_ephemeral'] = true;
    if (function_exists('mam_log')) {
        mam_log('error', 'app_key_not_persisted', [
            'file'   => $file,
            'writable_dir' => is_dir(MAM_STORAGE) ? is_writable(MAM_STORAGE) : false,
            'impact' => 'APP_KEY is unset AND storage/.app_key could not be written, so each process signs with a different key. Every form will fail with csrf_invalid and every signed link will be rejected. Fix: set APP_KEY (32+ chars) in api/.env, or make api/storage writable.',
        ]);
    }
    return $key = $generated;
}

/**
 * Is the signing key STABLE across processes?
 *
 * False means the key is regenerated per process — see the block above. A
 * caller reporting on system health must use this rather than measuring the
 * key's length: an ephemeral key is a perfectly well-formed 64 characters, so
 * a length check reports "fine" in exactly the state where nothing works.
 */
function mam_app_key_persisted(): bool {
    mam_app_key();                       // resolve it, so the flag is set
    return empty($GLOBALS['__mam_app_key_ephemeral']);
}

/**
 * Per-session binding folded into the token signature: the current session's
 * token hash, or '' for an anonymous caller (public apply/contact/newsletter
 * forms). This stops a token minted in one user's context from validating
 * another user's state-changing request. A token whose binding no longer
 * matches (e.g. minted before login) fails verification; the client's
 * MAM_API.request() transparently refetches once on `csrf_invalid`.
 */
function mam_csrf_binding(): string {
    if (function_exists('mam_session_current_hash')) {
        $h = mam_session_current_hash();
        if (is_string($h) && $h !== '') return $h;
    }
    return '';
}

function mam_csrf_token(): string {
    $key = mam_app_key();
    if (!$key) return '';
    $ts = time();
    $nonce = bin2hex(random_bytes(8));
    $payload = $ts . '.' . $nonce;
    $sig = hash_hmac('sha256', $payload . '.' . mam_csrf_binding(), $key);
    return $payload . '.' . $sig;
}

function mam_csrf_verify(?string $token, int $maxAgeSec = 7200): bool {
    if (!$token) return false;
    $key = mam_app_key();
    if (!$key) return false;
    $parts = explode('.', $token);
    if (count($parts) !== 3) return false;
    [$ts, $nonce, $sig] = $parts;
    if (!ctype_digit($ts)) return false;
    if (time() - (int)$ts > $maxAgeSec) return false;
    $expected = hash_hmac('sha256', $ts . '.' . $nonce . '.' . mam_csrf_binding(), $key);
    return hash_equals($expected, $sig);
}

function mam_csrf_require(): void {
    $hdr = $_SERVER['HTTP_X_CSRF_TOKEN'] ?? '';
    if (!mam_csrf_verify($hdr)) mam_fail('csrf_invalid', 403);
}
